// AllInterfaceTypes lists every InterfaceType in registry order.
func AllInterfaceTypes() []InterfaceType {
	return append([]InterfaceType(nil), interfaceTypeValues...)
}

// InterfaceTypeLabel is the UI label ("" for an unknown value).
func InterfaceTypeLabel(t InterfaceType) string { return interfaceTypeLabels[t] }

// ParseInterfaceType returns the value for a registry key.
func ParseInterfaceType(s string) (InterfaceType, bool) {
	t := InterfaceType(s)
	_, ok := interfaceTypeLabels[t]
	return t, ok
}

