// AllPowerPortTypes lists every PowerPortType in registry order.
func AllPowerPortTypes() []PowerPortType {
	return append([]PowerPortType(nil), powerPortTypeValues...)
}

// PowerPortTypeLabel is the UI label ("" for an unknown value).
func PowerPortTypeLabel(t PowerPortType) string { return powerPortTypeLabels[t] }

// ParsePowerPortType returns the value for a registry key.
func ParsePowerPortType(s string) (PowerPortType, bool) {
	t := PowerPortType(s)
	_, ok := powerPortTypeLabels[t]
	return t, ok
}

