// AllWirelessChannels lists every wireless channel in registry order.
func AllWirelessChannels() []WirelessChannel {
	return append([]WirelessChannel(nil), wirelessChannels...)
}

// ParseWirelessChannel returns the channel for a registry key.
func ParseWirelessChannel(key string) (WirelessChannel, bool) {
	for _, c := range wirelessChannels {
		if c.Key == key {
			return c, true
		}
	}
	return WirelessChannel{}, false
}

// compatibleTerminations is the termination compatibility matrix (NetBox
// COMPATIBLE_TERMINATION_TYPES), written out in both directions.
var compatibleTerminations = map[ObjectKind][]ObjectKind{
	ObjectKindCircuitTermination: {ObjectKindCircuitTermination, ObjectKindFrontPort, ObjectKindInterface, ObjectKindRearPort},
	ObjectKindConsolePort:        {ObjectKindConsoleServerPort, ObjectKindFrontPort, ObjectKindRearPort},
	ObjectKindConsoleServerPort:  {ObjectKindConsolePort, ObjectKindFrontPort, ObjectKindRearPort},
	ObjectKindFrontPort:          {ObjectKindCircuitTermination, ObjectKindConsolePort, ObjectKindConsoleServerPort, ObjectKindFrontPort, ObjectKindInterface, ObjectKindRearPort},
	ObjectKindInterface:          {ObjectKindCircuitTermination, ObjectKindFrontPort, ObjectKindInterface, ObjectKindRearPort},
	ObjectKindPowerFeed:          {ObjectKindPowerPort},
	ObjectKindPowerOutlet:        {ObjectKindPowerPort},
	ObjectKindPowerPort:          {ObjectKindPowerFeed, ObjectKindPowerOutlet},
	ObjectKindRearPort:           {ObjectKindCircuitTermination, ObjectKindConsolePort, ObjectKindConsoleServerPort, ObjectKindFrontPort, ObjectKindInterface, ObjectKindRearPort},
}

// CableCompatible reports whether a cable may join a termination of kind a to one of kind b.
func CableCompatible(a, b ObjectKind) bool {
	for _, k := range compatibleTerminations[a] {
		if k == b {
			return true
		}
	}
	return false
}

// CableCompatibleKinds lists the termination kinds a may be cabled to, sorted by key.
func CableCompatibleKinds(a ObjectKind) []ObjectKind {
	return append([]ObjectKind(nil), compatibleTerminations[a]...)
}
